DROP FUNCTION IF EXISTS `FiltSql`$$
CREATE FUNCTION `FiltSql`(p_FiltSql VARCHAR(1000)) RETURNS INT
NOT DETERMINISTIC READS SQL DATA
fn: BEGIN
  DECLARE v_result INT DEFAULT NULL;
  DECLARE v_f1 VARCHAR(20) DEFAULT NULL;
  DECLARE v_f2 VARCHAR(20) DEFAULT NULL;
  DECLARE v_f3 VARCHAR(20) DEFAULT NULL;
  DECLARE v_f4 VARCHAR(20) DEFAULT NULL;
  DECLARE v_f5 VARCHAR(20) DEFAULT NULL;
  DECLARE v_f6 VARCHAR(20) DEFAULT NULL;
  DECLARE v_f7 VARCHAR(20) DEFAULT NULL;
  SET v_f1 = 'update ';
  SET v_f2 = 'insert ';
  SET v_f3 = 'table ';
  SET v_f4 = 'delete ';
  SET v_f5 = 'drop ';
  SET v_f6 = 'exec ';
  SET v_f7 = 'select ';
  SET v_result = 1;
  IF ((LOCATE(v_f1, p_FiltSql, 1) > 0) OR (LOCATE(v_f2, p_FiltSql, 1) > 0) OR (LOCATE(v_f3, p_FiltSql, 1) > 0) OR (LOCATE(v_f4, p_FiltSql, 1) > 0) OR (LOCATE(v_f5, p_FiltSql, 1) > 0) OR (LOCATE(v_f6, p_FiltSql, 1) > 0) OR (LOCATE(v_f7, p_FiltSql, 1) > 0)) THEN
    SET v_result = 0;
  END IF;
  RETURN v_result;
END$$

DROP FUNCTION IF EXISTS `GetTranslation`$$
CREATE FUNCTION `GetTranslation`(p_TranslationID VARCHAR(200)) RETURNS VARCHAR(200)
NOT DETERMINISTIC READS SQL DATA
fn: BEGIN
  DECLARE v_language VARCHAR(200) DEFAULT NULL;
  DECLARE v_translated VARCHAR(200) DEFAULT NULL;
  SET v_language = 'Vietnam';
  SELECT IFNULL(`value`, 'Vietnam') INTO v_language FROM `Server_Config` WHERE `Name` = 'Language' LIMIT 1;
  SET v_translated = CASE v_language WHEN 'Chinese' THEN `ChineseTranslation`(p_TranslationID) WHEN 'English' THEN `EnglishTranslation`(p_TranslationID) WHEN 'Traditional' THEN `TraditionalTranslation`(p_TranslationID) WHEN 'Vietnam' THEN `VietnamTranslation`(p_TranslationID) WHEN 'Portuguese' THEN `TraditionalTranslation`(p_TranslationID) ELSE `ChineseTranslation`(p_TranslationID) END;
  RETURN v_translated;
END$$

