'<{0}> tuyên chiến, thù địch!' WHEN 'SP_ConsortiaAlly_Add.Msg2' THEN ' Chuyển sang trạng thái thù địch với <{0}>!' WHEN 'SP_ConsortiaAlly_Add.Msg3' THEN '<{0}> Thoát liên minh, trung lập!' WHEN 'SP_ConsortiaAlly_Add.Msg4' THEN ' Cùng <{0}> bỏ liên minh, trung lập!' WHEN 'SP_ConsortiaApplyAlly_Pass.Msg1' THEN 'Đã liên minh với <{0}>!' WHEN 'SP_ConsortiaApplyAlly_Pass.Msg2' THEN '<{0}> và bạn liên minh thành công!' WHEN 'SP_ConsortiaApplyAlly_Pass.Msg3' THEN 'Đã nghị hòa với <{0}>!' WHEN 'SP_ConsortiaApplyAlly_Pass.Msg4' THEN '<{0}> đã nghị hòa với guild bạn!' WHEN 'SP_Mail_Delete.Msg1' THEN 'Thư trả về:   ' WHEN 'SP_Mail_Delete.Msg2' THEN 'Thư bạn gửi cho <{0}> bị đối phương từ chối hay vượt quá thời gian cho phép nên bị trả về!' WHEN 'SP_Mail_PaymentCancel.Msg1' THEN 'hư trả về:    ' WHEN 'SP_Mail_PaymentCancel.Msg2' THEN 'Thư bạn gửi cho <{0}> bị đối phương từ chối hay vượt quá thời gian cho phép nên bị trả về!' WHEN 'SP_Mail_Scan.Sender' THEN 'Trung tâm bán đấu giá' WHEN 'SP_Mail_Scan.Title' THEN 'Bán đấu giá thành công!' WHEN 'SP_Mail_Scan.Content' THEN 'Bán đấu giá thành công!' WHEN 'SP_Mail_Scan.Msg1' THEN 'Thư trả về:    ' WHEN 'SP_Mail_Scan.Msg2' THEN 'Thư bạn gửi cho <{0}> bị đối phương từ chối hay vượt quá thời gian cho phép nên bị trả về!' WHEN 'SP_Mail_Update.Msg1' THEN 'Thư trả tiền:    ' WHEN 'SP_Mail_Update.Msg2' THEN 'Bạn gửi cho <{0}> {1} đã được thanh toán, số tiền là {2} điểm khoán!' WHEN 'SP_Consortia_Riches_Add.Msg1' THEN ' Member {0} tặng {1} điểm tài sản!' WHEN 'SP_Mail_Update.Msg3' THEN 'đính kèm:1、xu{0}' WHEN 'SP_Admin_SendAllItem.Sender' THEN ' Quản lý ' ELSE p_TranslationID END;
