DROP PROCEDURE IF EXISTS `SP_Insert_Update_Achievement`$$
CREATE PROCEDURE `SP_Insert_Update_Achievement`(IN p_ID INT, IN p_PlaceID INT, IN p_Title VARCHAR(100), IN p_Detail VARCHAR(500), IN p_NeedMinLevel INT, IN p_NeedMaxLevel INT, IN p_PreAchievementID VARCHAR(100), IN p_IsOther INT, IN p_AchievementType INT, IN p_CanHide TINYINT(1), IN p_StartDate DATETIME(3), IN p_EndDate DATETIME(3), IN p_AchievementPoint INT, IN p_IsActive INT, IN p_PicID INT, IN p_IsShare TINYINT(1), IN p_setUpdate INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_count2 INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT IFNULL(COUNT(*), 0) INTO v_count2 FROM `Achievement` WHERE `ID` = p_ID LIMIT 1;
  IF (v_count2 <> 0 AND p_setUpdate = 0) THEN
    UPDATE `Achievement` SET `ID` = p_ID, `PlaceID` = p_PlaceID, `Title` = p_Title, `Detail` = p_Detail, `NeedMinLevel` = p_NeedMinLevel, `NeedMaxLevel` = p_NeedMaxLevel, `PreAchievementID` = p_PreAchievementID, `IsOther` = p_IsOther, `AchievementType` = p_AchievementType, `CanHide` = p_CanHide, `StartDate` = p_StartDate, `EndDate` = p_EndDate, `AchievementPoint` = p_AchievementPoint, `IsActive` = p_IsActive, `PicID` = p_PicID, `IsShare` = p_IsShare WHERE `ID` = p_ID;
    SET p_ReturnValue = 1;
    LEAVE proc;
  ELSE
    INSERT INTO `Achievement` (`ID`, `PlaceID`, `Title`, `Detail`, `NeedMinLevel`, `NeedMaxLevel`, `PreAchievementID`, `IsOther`, `AchievementType`, `CanHide`, `StartDate`, `EndDate`, `AchievementPoint`, `IsActive`, `PicID`, `IsShare`) VALUES (p_ID, p_PlaceID, p_Title, p_Detail, p_NeedMinLevel, p_NeedMaxLevel, p_PreAchievementID, p_IsOther, p_AchievementType, p_CanHide, p_StartDate, p_EndDate, p_AchievementPoint, p_IsActive, p_PicID, p_IsShare);
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  IF (0 <> 0) THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
END$$

