  SELECT IFNULL(COUNT(*), 0) INTO v_count FROM `Shop_Goods_Categorys` WHERE `ID` = p_ID LIMIT 1;
  IF (v_count <> 0 AND p_setUpdate = 0) THEN
    UPDATE `Shop_Goods_Categorys` SET `ID` = p_ID, `Name` = p_Name, `Place` = p_Place, `Remark` = p_Remark WHERE `ID` = p_ID;
    SET p_ReturnValue = 1;
    LEAVE proc;
  ELSE
    INSERT INTO `Shop_Goods_Categorys` (`ID`, `Name`, `Place`, `Remark`) VALUES (p_ID, p_Name, p_Place, p_Remark);
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  IF (0 <> 0) THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
END$$

DROP PROCEDURE IF EXISTS `SP_Insert_Update_TemplateAlllist`$$
CREATE PROCEDURE `SP_Insert_Update_TemplateAlllist`(IN p_TemplateID INT, IN p_Name VARCHAR(50), IN p_CategoryID INT, IN p_Description VARCHAR(200), IN p_Attack INT, IN p_Defence INT, IN p_Agility INT, IN p_Luck INT, IN p_Level INT, IN p_Quality INT, IN p_Pic VARCHAR(200), IN p_MaxCount INT, IN p_NeedSex INT, IN p_NeedLevel INT, IN p_CanStrengthen TINYINT(1), IN p_CanCompose TINYINT(1), IN p_CanDrop TINYINT(1), IN p_CanEquip TINYINT(1), IN p_CanUse TINYINT(1), IN p_CanDelete TINYINT(1), IN p_Script VARCHAR(200), IN p_Data VARCHAR(1000), IN p_Colors VARCHAR(1000), IN p_Property1 INT, IN p_Property2 INT, IN p_Property3 INT, IN p_Property4 INT, IN p_Property5 INT, IN p_Property6 INT, IN p_Property7 INT, IN p_Property8 INT, IN p_BindType INT, IN p_FusionType INT, IN p_FusionRate INT, IN p_FusionNeedRate INT, IN p_Hole VARCHAR(50), IN p_RefineryLevel INT, IN p_ReclaimValue INT, IN p_ReclaimType INT, IN p_CanRecycle INT, IN p_SuitId INT, IN p_setUpdate INT, OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_countItems INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT IFNULL(COUNT(*), 0) INTO v_countItems FROM `Shop_Goods` WHERE `TemplateID` = p_TemplateID LIMIT 1;
  IF (v_countItems <> 0 AND p_setUpdate = 0) THEN
    UPDATE `Shop_Goods` SET `TemplateID` = p_TemplateID, `Name` = p_Name, `Remark` = '', `CategoryID` = p_CategoryID, `Description` = p_Description, `Attack` = p_Attack, `Defence` = p_Defence, `Agility` = p_Agility, `Luck` = p_Luck, `Level` = p_Level, `Quality` = p_Quality, `Pic` = p_Pic, `MaxCount` = p_MaxCount, `NeedSex` = p_NeedSex, `NeedLevel` = p_NeedLevel, `CanStrengthen` = p_CanStrengthen, `CanCompose` = p_CanCompose, `CanDrop` = p_CanDrop, `CanEquip` = p_CanEquip, `CanUse` = p_CanUse, `CanDelete` = p_CanDelete, `Script` = p_Script, `Data` = p_Data, `Colors` = p_Colors, `Property1` = p_Property1, `Property2` = p_Property2, `Property3` = p_Property3, `Property4` = p_Property4, `Property5` = p_Property5, `Property6` = p_Property6, `Property7` = p_Property7, `Property8` = p_Property8, `Valid` = 0, `Count` = 0, `AddTime` = NOW(3), `BindType` = p_BindType, `FusionType` = p_FusionType, `FusionRate` = p_FusionRate, `FusionNeedRate` = p_FusionNeedRate, `Hole` = p_Hole, `RefineryLevel` = p_RefineryLevel, `ReclaimValue` = p_ReclaimValue, `ReclaimType` = p_ReclaimType, `CanRecycle` = p_CanRecycle, `SuitId` = p_SuitId WHERE `TemplateID` = p_TemplateID;
    SET p_ReturnValue = 1;
    LEAVE proc;
  ELSE
    INSERT INTO `Shop_Goods` (`TemplateID`, `Name`, `Remark`, `CategoryID`, `Description`, `Attack`, `Defence`, `Agility`, `Luck`, `Level`, `Quality`, `Pic`, `MaxCount`, `NeedSex`, `NeedLevel`, `CanStrengthen`, `CanCompose`, `CanDrop`, `CanEquip`, `CanUse`, `CanDelete`, `Script`, `Data`, `Colors`, `Property1`, `Property2`, `Property3`, `Property4`, `Property5`, `Property6`, `Property7`, `Property8`, `Valid`, `Count`, `AddTime`, `BindType`, `FusionType`, `FusionRate`, `FusionNeedRate`, `Hole`, `RefineryLevel`, `ReclaimValue`, `ReclaimType`, `CanRecycle`, `SuitId`) VALUES (p_TemplateID, p_Name, '', p_CategoryID, p_Description, p_Attack, p_Defence, p_Agility, p_Luck, p_Level, p_Quality, p_Pic, p_MaxCount, p_NeedSex, p_NeedLevel, p_CanStrengthen, p_CanCompose, p_CanDrop, p_CanEquip, p_CanUse, p_CanDelete, p_Script, p_Data, p_Colors, p_Property1, p_Property2, p_Property3, p_Property4, p_Property5, p_Property6, p_Property7, p_Property8, 0, 0, NOW(3), p_BindType, p_FusionType, p_FusionRate, p_FusionNeedRate, p_Hole, p_RefineryLevel, p_ReclaimValue, p_ReclaimType, p_CanRecycle, p_SuitId);
    SET p_ReturnValue = 0;
    LEAVE proc;
  END IF;
  IF (0 <> 0) THEN
    SET p_ReturnValue = 2;
    LEAVE proc;
  END IF;
END$$

