DROP PROCEDURE IF EXISTS `SP_Server_Config_Update`$$
CREATE PROCEDURE `SP_Server_Config_Update`(IN p_Key VARCHAR(50), IN p_Value VARCHAR(2000), OUT p_ReturnValue INT)
proc: BEGIN
  DECLARE v_Counts INT DEFAULT NULL;
  DECLARE v_Maxs INT DEFAULT NULL;
  SET p_ReturnValue = 0;
  SELECT IFNULL(COUNT(*), 0) INTO v_Counts FROM `Server_Config` WHERE `Name` = p_Key LIMIT 1;
  SELECT IFNULL(MAX(`id`), 0) + 1 INTO v_Maxs FROM `Server_Config` LIMIT 1;
  IF v_Counts = 1 THEN
    UPDATE `Server_Config` SET `Value` = p_Value WHERE `Name` = p_Key;
  ELSE
    INSERT INTO `Server_Config` (`Id`, `Name`, `Value`) VALUES (v_Maxs, p_Key, p_Value);
  END IF;
END$$

